import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;
@WebServlet("/profile") public class ProfileServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{if(!Security.requireUser(q,p))return;int id=Security.userId(q);try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement("SELECT u.user_id,u.full_name,u.email,u.phone_number,u.country_id,u.state_id,u.address,u.latitude,u.longitude,u.district,u.locality,u.accuracy_m,c.country_name,st.state_name FROM users u LEFT JOIN countries c ON c.country_id=u.country_id LEFT JOIN states st ON st.state_id=u.state_id WHERE u.user_id=?")){s.setInt(1,id);try(ResultSet r=s.executeQuery()){if(!r.next()){Security.json(p,404,"{\"message\":\"Profile not found.\"}");return;}String json="{\"status\":\"success\",\"userId\":"+id+",\"fullName\":"+Security.quote(r.getString("full_name"))+",\"email\":"+Security.quote(r.getString("email"))+",\"phoneNumber\":"+Security.quote(r.getString("phone_number"))+",\"countryId\":"+nullable(r,"country_id")+",\"countryName\":"+Security.quote(r.getString("country_name"))+",\"stateId\":"+nullable(r,"state_id")+",\"stateName\":"+Security.quote(r.getString("state_name"))+",\"district\":"+Security.quote(r.getString("district"))+",\"locality\":"+Security.quote(r.getString("locality"))+",\"address\":"+Security.quote(r.getString("address"))+",\"latitude\":"+decimal(r,"latitude")+",\"longitude\":"+decimal(r,"longitude")+",\"accuracy\":"+decimal(r,"accuracy_m")+",\"profileComplete\":"+(r.getString("district")!=null&&r.getString("locality")!=null&&r.getString("address")!=null)+"}";Security.json(p,200,json);}}catch(Exception e){Security.json(p,503,"{\"status\":\"error\",\"message\":\"Could not load profile.\"}");}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{if(!Security.requireUser(q,p))return;q.setCharacterEncoding("UTF-8");String name=v(q,"fullName"),email=v(q,"email"),phone=v(q,"phoneNumber"),district=v(q,"district"),locality=v(q,"locality"),address=v(q,"address");int country=integer(q,"countryId"),state=integer(q,"stateId");Double lat=number(q,"latitude"),lng=number(q,"longitude"),acc=number(q,"accuracy");if(name.length()<2||!email.matches("(?i)^[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}$")||!phone.matches("\\+?[0-9 ()-]{8,20}")||district.isBlank()||locality.isBlank()||address.isBlank()||country<1||state<1||(lat!=null&&(lat < -90||lat>90))||(lng!=null&&(lng < -180||lng>180))||(lat==null)!=(lng==null)){Security.json(p,400,"{\"status\":\"error\",\"message\":\"Complete all required profile fields with valid values. GPS coordinates must be a valid pair.\"}");return;}
 try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement("UPDATE users SET full_name=?,email=?,phone_number=?,country_id=?,state_id=?,district=?,locality=?,address=?,latitude=?,longitude=?,accuracy_m=? WHERE user_id=?")){s.setString(1,name);s.setString(2,email);s.setString(3,phone);s.setInt(4,country);s.setInt(5,state);s.setString(6,district);s.setString(7,locality);s.setString(8,address);if(lat==null){s.setNull(9,Types.DECIMAL);s.setNull(10,Types.DECIMAL);s.setNull(11,Types.DECIMAL);}else{s.setDouble(9,lat);s.setDouble(10,lng);if(acc==null)s.setNull(11,Types.DECIMAL);else s.setDouble(11,acc);}s.setInt(12,Security.userId(q));if(s.executeUpdate()==0){Security.json(p,404,"{\"message\":\"Profile not found.\"}");return;}Security.json(p,200,"{\"status\":\"success\",\"message\":\"Profile saved.\"}");}catch(SQLIntegrityConstraintViolationException e){Security.json(p,409,"{\"status\":\"error\",\"message\":\"Email or phone number already belongs to another account.\"}");}catch(Exception e){Security.json(p,503,"{\"status\":\"error\",\"message\":\"Profile could not be saved.\"}");}}
 private String v(HttpServletRequest q,String n){String s=q.getParameter(n);return s==null?"":s.trim();}private int integer(HttpServletRequest q,String n){try{return Integer.parseInt(v(q,n));}catch(Exception e){return -1;}}private Double number(HttpServletRequest q,String n){try{String s=v(q,n);return s.isEmpty()?null:Double.valueOf(s);}catch(Exception e){return null;}}private String nullable(ResultSet r,String n)throws SQLException{int x=r.getInt(n);return r.wasNull()?"null":String.valueOf(x);}private String decimal(ResultSet r,String n)throws SQLException{double x=r.getDouble(n);return r.wasNull()?"null":String.valueOf(x);}
}
